Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
Design a waiter that blocks on a condition variable until a predicate protected by the mutex becomes true, and a notifier that makes the predicate true and signals. The waiter must terminate even if the notifier signals before the waiter waits.
</domain_requirements>

<contract>
{
  "name": "bare-wait",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    },
    {
      "kind": "reachability",
      "id": "ready-set",
      "goal": {
        "kind": "var_eq",
        "resource": "main::ready",
        "value": true
      }
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::waiter completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::waiter"
      }
    },
    {
      "kind": "reachable",
      "description": "main::notifier completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::notifier"
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

